"use client";

import * as React from "react";
import { Tabs as TabsPrimitive } from "@base-ui/react/tabs";

import { cn } from "@/lib/utils";

type WithClassName<P> = Omit<P, "className"> & { className?: string };

/** Playful console Tabs root: owns which panel shows. */
const Tabs = TabsPrimitive.Root;

/**
 * Playful console TabsList: a cream tray that holds the tabs. The active tab
 * lifts out of it as a white card.
 */
const TabsList = React.forwardRef<
  HTMLDivElement,
  WithClassName<TabsPrimitive.List.Props>
>(({ className, ...props }, ref) => (
  <TabsPrimitive.List
    ref={ref}
    data-slot="tabs-list"
    className={cn(
      "inline-flex items-center gap-1 rounded-lg bg-secondary p-1 text-(--foreground-secondary)",
      className,
    )}
    {...props}
  />
));
TabsList.displayName = "TabsList";

/**
 * Playful console TabsTrigger: semibold secondary ink that darkens on hover.
 * The active tab becomes a white card with the olive hairline and a thin slab.
 */
const TabsTrigger = React.forwardRef<
  HTMLButtonElement,
  WithClassName<TabsPrimitive.Tab.Props>
>(({ className, ...props }, ref) => (
  <TabsPrimitive.Tab
    ref={ref}
    data-slot="tabs-trigger"
    className={cn(
      "inline-flex h-8 shrink-0 items-center justify-center gap-2 whitespace-nowrap rounded-md border border-transparent px-3",
      "text-sm font-semibold text-(--foreground-secondary)",
      "transition-[background-color,color,border-color] duration-fast ease-out hover:text-foreground",
      "data-[active]:border-border data-[active]:bg-card data-[active]:text-foreground data-[active]:shadow-(--shadow-control-off)",
      "focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-ring",
      "data-[disabled]:cursor-not-allowed data-[disabled]:text-(--foreground-disabled)",
      "[&_svg]:pointer-events-none [&_svg]:size-4 [&_svg]:shrink-0",
      className,
    )}
    {...props}
  />
));
TabsTrigger.displayName = "TabsTrigger";

/** Playful console TabsContent: the active panel, set a little below the tab tray. */
const TabsContent = React.forwardRef<
  HTMLDivElement,
  WithClassName<TabsPrimitive.Panel.Props>
>(({ className, ...props }, ref) => (
  <TabsPrimitive.Panel
    ref={ref}
    data-slot="tabs-content"
    className={cn(
      "mt-4 rounded-md focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-ring",
      className,
    )}
    {...props}
  />
));
TabsContent.displayName = "TabsContent";

export { Tabs, TabsList, TabsTrigger, TabsContent };
